require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';if(!is_attendee_logged_in())redirect('../index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$fineId=(int)($_POST['fine_id']??0);$method=$_POST['payment_method']??'online';$receipt=trim($_POST['receipt_number']??'');$r=pg_query_params($conn,"SELECT * FROM fines WHERE id=$1 AND attendee_id=$2 AND status IN ('unpaid','pending_verification')",[$fineId,$_SESSION['attendee_id']]);if(!$r||!pg_num_rows($r))$error='Payable fine not found.';else{$fine=pg_fetch_assoc($r);$path=save_receipt_upload($_FILES['receipt']??null,$error);if(!$error){pg_query($conn,'BEGIN');$ok=pg_query_params($conn,'INSERT INTO payments(attendee_id,fine_id,amount,payment_method,receipt_number,receipt_path) VALUES($1,$2,$3,$4,$5,$6)',[$_SESSION['attendee_id'],$fineId,$fine['amount'],$method,$receipt?:null,$path]);pg_query_params($conn,"UPDATE fines SET status='pending_verification' WHERE id=$1",[$fineId]);pg_query($conn,$ok?'COMMIT':'ROLLBACK');if($ok)redirect('payments.php?submitted=1');$error='Payment could not be submitted.';}}}}
$fines=pg_query_params($conn,"SELECT f.*,e.title FROM fines f LEFT JOIN events e ON e.id=f.event_id WHERE f.attendee_id=$1 ORDER BY f.created_at DESC",[$_SESSION['attendee_id']]);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fines & Payments</title><link rel="stylesheet" href="../assets/css/feedback.css"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap" rel="stylesheet"></head><body class="feedback-ballot vms-participant" style="--feedback-bg:url('../<?=h(site_background())?>')"><div class="participant-wrapper"><div class="participant-container"><header class="participant-topbar"><strong>My Fines & Payments</strong><a class="btn secondary" href="dashboard.php">My Events</a></header><?php if(isset($_GET['submitted'])):?><div class="participant-alert" style="background:#dcfce7;color:#166534">Receipt submitted for verification.</div><?php endif;?><?php if($error):?><div class="participant-alert error"><?=h($error)?></div><?php endif;?><?php if($fines):while($f=pg_fetch_assoc($fines)):?><div class="position-card"><div class="position-title"><?=h($f['title']?:'Attendance Fine')?> <span class="badge <?=h($f['status'])?>" style="margin-left:auto"><?=h(ucwords(str_replace('_',' ',$f['status'])))?></span></div><p><?=h($f['description'])?></p><h2>₱<?=number_format((float)$f['amount'],2)?></h2><?php if($f['status']==='unpaid'):?><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="fine_id" value="<?=(int)$f['id']?>"><div class="field"><label>Payment method</label><select name="payment_method"><option value="online">Online payment</option><option value="cash">Cash / paper receipt</option><option value="other">Other</option></select></div><div class="field"><label>Receipt number</label><input name="receipt_number"></div><div class="field full"><label>Receipt photo</label><input type="file" name="receipt" accept="image/jpeg,image/png,image/webp" required></div><div class="field full"><button class="btn">Submit Payment Receipt</button></div></form><?php endif;?></div><?php endwhile;endif;?></div></div></body></html>
